# --- GRTools tracked-capture preamble (ENV-overridable paths) ---------------------------------
const REFCODE_ROOT         = get(ENV, "GRTOOLS_REFCODE_ROOT",         "/data/haiyangw/claude/emri-disk/ref-code")
const FIXTURE_DIR          = get(ENV, "GRTOOLS_FIXTURE_OUT_DIR",      normpath(joinpath(@__DIR__, "..")))
# ----------------------------------------------------------------------------------------------

# gen_np0_fixture.jl — emit test/fixtures/npghp_np0_fixture.jl (Julia literals) by running the
# UPSTREAM oracle TeukEvolution.jl/src/BackgroundNP.jl on the same grid as np0_fixture.txt.
# This is the baked-fixture philosophy: the fixture is a frozen characterization of the upstream
# module's actual output (Float64 √2 artifact included — see quirk-4), so G-B1 compares the
# Spacetime.NPGHP reimplementation against it. BigFloat stored as decimal strings (parsed under
# setprecision(256) in-test) so the file is precision-portable.

using Printf
include("$(REFCODE_ROOT)/TeukEvolution.jl/src/BackgroundNP.jl")
using .BackgroundNP: NP_0

setprecision(BigFloat, 256)

Rlabels = ["0.05", "0.35", "0.7", "0.99"]
thetas  = [(1, 6), (1, 2), (3, 4)]                 # θ = num·π/den
configs = [("0.0", :one), ("0.5", :one), ("0.9", :one), ("0.7", :sqrt2)]
fieldnames_np = (:mu_0, :tau_0, :pi_0, :rho_0, :eps_0, :psi2_0)

function build_grid(::Type{T}) where {T<:Real}
    Rvals = T[parse(T, s) for s in Rlabels]
    Cvals = T[]; Svals = T[]
    for (num, den) in thetas
        θ = (num * (T <: BigFloat ? big(π) : convert(T, π))) / den
        push!(Cvals, cos(θ)); push!(Svals, sin(θ))
    end
    Yvals = T[-c for c in Cvals]
    return Rvals, Yvals, Cvals, Svals
end

function build_params(::Type{T}, cfg) where {T<:Real}
    bhm = one(T)
    bhs = parse(T, cfg[1])
    cl  = cfg[2] === :one ? one(T) : sqrt(convert(T, 2))
    return bhm, bhs, cl
end

function make_np(::Type{T}, cfg) where {T<:Real}
    Rvals, Yvals, Cvals, Svals = build_grid(T)
    bhm, bhs, cl = build_params(T, cfg)
    NP_0{T}(Rvals=Rvals, Yvals=Yvals, Cvals=Cvals, Svals=Svals, bhm=bhm, bhs=bhs, cl=cl),
        Rvals, Cvals, Svals
end

f64(x) = @sprintf("%.17e", x)                       # round-trippable Float64
bfs(x) = @sprintf("%.60e", x)                       # 60 sig-digits > 256-bit (~77 dec) is unneeeded;
                                                    # 60 covers what we test at rtol 1e-30

io = IOBuffer()
println(io, "# npghp_np0_fixture.jl — GENERATED, do not hand-edit.")
println(io, "#")
println(io, "# Baked characterization of the UPSTREAM oracle TeukEvolution.jl/src/BackgroundNP.jl")
println(io, "# (NP_0 struct, verbatim closed forms transcribed in R_teuk.md §3b). Generated by")
println(io, "# scratchpad/npghp_moveB/gen_np0_fixture.jl on the exact grid of np0_fixture.txt (694 lines):")
println(io, "#   R ∈ {0.05,0.35,0.7,0.99}, θ ∈ {π/6,π/2,3π/4}, (bhs,cl) ∈ {(0,1),(0.5,1),(0.9,1),(0.7,√2)},")
println(io, "#   bhm = 1 (M=1 canon). Float64 block = the module's actual output (Float64 √2 artifact")
println(io, "#   INCLUDED — quirk-4); BigFloat block = 256-bit strings (module value, i.e. also carries the")
println(io, "#   Float64-√2 cap on tau_0/pi_0; the true-closed-form check lives separately in test_npghp.jl G-B1).")
println(io, "module NPGHPNp0Fixture")
println(io)
println(io, "# grid axes (θ = num·π/den)")
println(io, "const RLABELS = [\"0.05\", \"0.35\", \"0.7\", \"0.99\"]")
println(io, "const THETAS  = [(1,6), (1,2), (3,4)]")
println(io, "# configs: (bhs_string, cl_kind); bhm = 1")
println(io, "const CONFIGS = [(\"0.0\", :one), (\"0.5\", :one), (\"0.9\", :one), (\"0.7\", :sqrt2)]")
println(io)
println(io, "# Float64 rows: key (ci,ri,ti) -> NamedTuple of the 6 NP_0 scalars as ComplexF64.")
println(io, "const F64 = Dict{NTuple{3,Int},NamedTuple}(")
for (ci, cfg) in enumerate(configs)
    npF, _, _, _ = make_np(Float64, cfg)
    for ti in 1:length(thetas), ri in 1:length(Rlabels)
        vals = join(["$(String(fn)) = complex($(f64(real(getfield(npF, fn)[ri, ti]))), $(f64(imag(getfield(npF, fn)[ri, ti]))))"
                     for fn in fieldnames_np], ", ")
        println(io, "    ($ci,$ri,$ti) => (; $vals),")
    end
end
println(io, ")")
println(io)
println(io, "# BigFloat rows: key (ci,ri,ti) -> NamedTuple of (re_string, im_string) pairs per scalar.")
println(io, "# Reconstruct in-test: Complex{BigFloat}(parse(BigFloat, re), parse(BigFloat, im)) under setprecision(256).")
println(io, "const BF_STR = Dict{NTuple{3,Int},NamedTuple}(")
for (ci, cfg) in enumerate(configs)
    npB, _, _, _ = make_np(BigFloat, cfg)
    for ti in 1:length(thetas), ri in 1:length(Rlabels)
        vals = join(["$(String(fn)) = (\"$(bfs(real(getfield(npB, fn)[ri, ti])))\", \"$(bfs(imag(getfield(npB, fn)[ri, ti])))\")"
                     for fn in fieldnames_np], ", ")
        println(io, "    ($ci,$ri,$ti) => (; $vals),")
    end
end
println(io, ")")
println(io)
println(io, "end # module NPGHPNp0Fixture")

open("$(FIXTURE_DIR)/npghp_np0_fixture.jl", "w") do f
    write(f, String(take!(io)))
end
println("wrote npghp_np0_fixture.jl")
